mapper.update:
UPDATE fbs_oauth_token_family
SET binding_id = #{family.bindingId},
    binding_version = #{family.bindingVersion},
    status = 'ACTIVE',
    activated_at = #{family.activatedAt},
    version = version + 1
WHERE family_id = #{family.familyId}
  AND client_id = #{family.clientId}
  AND enterprise_id = #{family.tenantId}
  AND member_id = #{family.memberId}
  AND user_id = #{family.userId}
  AND CAST(product_code AS BINARY) = CAST(#{family.productCode} AS BINARY)
  AND source_code = #{family.sourceCode}
  AND connector_code = #{family.connectorCode}
  AND issuer_uri = #{family.issuerUri}
  AND resource_uri = #{family.resourceUri}
  AND scope_canonical = #{family.scopeCanonical}
  AND scope_digest = #{family.scopeDigest}
  AND principal_subject_digest = #{family.principalSubjectDigest}
  AND consent_intent = #{family.consentIntent,
        javaType=com.wx.fbsir.business.board.oauth.BoardOAuthConsentIntent,
        typeHandler=org.apache.ibatis.type.EnumTypeHandler}
  AND version = #{expectedVersion}
  AND status = 'PENDING_BINDING'
  AND current_refresh_generation = 0
  AND #{family.bindingId} IS NOT NULL
  AND #{family.bindingVersion} IS NOT NULL
  AND issued_at <= #{family.activatedAt}
  AND expires_at > #{family.activatedAt}

UPDATE fbs_oauth_token_family
SET current_refresh_generation = current_refresh_generation + 1,
    version = version + 1
WHERE family_id = #{familyId}
  AND version = #{expectedVersion}
  AND current_refresh_generation = #{expectedGeneration}
  AND status = 'ACTIVE'

UPDATE fbs_oauth_token_family
SET current_refresh_generation = current_refresh_generation + 1,
    version = version + 1
WHERE family_id = #{familyId}
  AND client_id = #{clientId}
  AND binding_id = #{bindingId}
  AND binding_version = #{bindingVersion}
  AND version = #{expectedVersion}
  AND current_refresh_generation = #{expectedGeneration}
  AND current_refresh_generation < 4294967295
  AND status = 'ACTIVE'
  AND issued_at <= #{rotatedAt}
  AND activated_at <= #{rotatedAt}
  AND expires_at > #{rotatedAt}

UPDATE fbs_oauth_token_family
SET status = 'REVOKED',
    terminated_at = #{revokedAt},
    version = version + 1
WHERE family_id = #{familyId}
  AND client_id = #{clientId}
  AND version = #{expectedVersion}
  AND status IN ('PENDING_BINDING', 'ACTIVE')
  AND issued_at <= #{revokedAt}
  AND (status = 'PENDING_BINDING' OR activated_at <= #{revokedAt})

UPDATE fbs_oauth_token_family
SET status = 'COMPROMISED',
    terminated_at = #{compromisedAt},
    version = version + 1
WHERE family_id = #{familyId}
  AND client_id = #{clientId}
  AND version = #{expectedVersion}
  AND status IN ('PENDING_BINDING', 'ACTIVE')
  AND issued_at <= #{compromisedAt}
  AND (status = 'PENDING_BINDING' OR activated_at <= #{compromisedAt})

UPDATE fbs_oauth_token_family
SET status = 'EXPIRED',
    terminated_at = #{expiredAt},
    version = version + 1
WHERE family_id = #{familyId}
  AND client_id = #{clientId}
  AND version = #{expectedVersion}
  AND status IN ('PENDING_BINDING', 'ACTIVE')
  AND issued_at <= #{expiredAt}
  AND expires_at <= #{expiredAt}
  AND (status = 'PENDING_BINDING' OR activated_at <= #{expiredAt})

