mapper.insert:
INSERT INTO fbs_oauth_receipt (receipt_id, action, client_id, authorization_request_id, authorization_code_id, family_id, token_id, binding_id, enterprise_id, member_id, user_id, principal_subject_digest, actor_type, actor_user_id, actor_subject_digest, correlation_id, payload_digest, evidence_level, created_at
, receipt_format_version, subject_generation, result_generation, causation_receipt_id, before_state_digest, after_state_digest ) VALUES (#{receiptId}, #{action}, #{clientId}, #{authorizationRequestId}, #{authorizationCodeId}, #{familyId}, #{tokenId}, #{bindingId}, #{tenantId}, #{memberId}, #{userId}, #{principalSubjectDigest}, #{actorType}, #{actorUserId}, #{actorSubjectDigest}, #{correlationId}, #{payloadDigest}, #{evidenceLevel}, #{createdAt}
, #{receiptFormatVersion}, #{subjectGeneration}, #{resultGeneration}, #{causationReceiptId}, #{beforeStateDigest}, #{afterStateDigest} )

